S.append(S2(c,B+' · 2','Nhóm phát triển phần mềm',card('Vai trò trong một dự án',T(tr('Vai trò','Việc chính',h=True)+tr('<b>Phân tích nghiệp vụ</b>','xác định yêu cầu khách hàng, <b>viết tài liệu mô tả chức năng</b>')+tr('<b>UI/UX</b>','giao diện <b>thuận tiện, dễ hiểu, dễ dùng</b>')+tr('<b>Front-end</b>','<b>HTML, CSS, JavaScript</b>: giao diện trên trình duyệt')+tr('<b>Back-end</b>','chạy ở máy chủ: <b>nghiệp vụ, truy vấn CSDL, trả dữ liệu</b>')+tr('<b>Kiểm thử (tester)</b>','<b>thiết kế ca thử, tìm và báo lỗi</b>'))),KEY('Phát triển phần mềm: <b>phân tích → thiết kế → lập trình → kiểm thử → bảo trì</b>.')))
