S.append(S2(c,B+' · 4','Chọn nghề và phát triển nghề nghiệp',card('Điều cần cân nhắc',P('Kết hợp <b>sở thích</b>, <b>năng lực bản thân</b> và <b>nhu cầu thị trường lao động</b> (không chỉ lương hay tên trường).','CNTT đổi rất nhanh → <b>học tập suốt đời</b>, cập nhật công nghệ.','Cần <b>kĩ năng mềm</b>: làm việc nhóm, giao tiếp, trình bày.','<b>Chứng chỉ</b> (mạng, CSDL, an toàn thông tin) <b>xác nhận năng lực</b>, hỗ trợ tìm việc — nhưng <b>không thay kinh nghiệm</b>, không bảo đảm lương cao.')),KEY('Điều kiện quan trọng nhất để theo nghề lâu dài: <b>thường xuyên học tập</b>.')))
