S.append(SELF(c,B+' · 5','Tự kiểm tra 2: không phải việc của sửa chữa bảo trì','Việc nào KHÔNG thuộc sửa chữa bảo trì máy tính: cài lại HĐH, tư vấn nâng cấp linh kiện, khắc phục lỗi phần cứng, hay thiết kế và lập trình phần mềm theo yêu cầu?','',P('<b>Thiết kế và lập trình phần mềm</b> thuộc nhóm nghề phát triển phần mềm.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) Chứng chỉ bảo đảm lương rất cao. (b) Back-end làm việc trên máy chủ, truy vấn CSDL. (c) Tester chứng minh chương trình hết lỗi. (d) Kĩ sư AI cần toán – thống kê, lập trình, xử lí dữ liệu. (e) Chỉ cần thuộc một ngôn ngữ lập trình là đủ cả sự nghiệp.','',P('(a) <b>Sai</b>.','(b) <b>Đúng</b>.','(c) <b>Sai</b>.','(d) <b>Đúng</b>.','(e) <b>Sai</b>: phải học suốt đời.'),20))
